/* plain-language labels for the level codes in mart.score_weight */
const LVL = {le_6m: "Within 6 months", le_12m: "6 to 12 months ago", le_18m: "12 to 18 months ago", le_24m: "18 to 24 months ago",
  le_36m: "2 to 3 years ago", gt_36m: "Over 3 years ago", lt_1m: "Under $1M", "1m_10m": "$1M to $10M", "10m_50m": "$10M to $50M",
  "50m_100m": "$50M to $100M", ge_100m: "$100M or more", "1-10": "1 to 10 people", "11-50": "11 to 50", "51-200": "51 to 200",
  "201-500": "201 to 500", "501-1000": "501 to 1,000", "1001+": "Over 1,000", unknown: "Not on file"};
const IND = {ai_native: "AI-native builders", fintech_banking: "banking and fintech", education: "education", health: "healthcare",
  public_sector: "public sector", creative_tools: "creative tools", ecommerce: "e-commerce", gaming: "gaming", hr_recruiting: "HR",
  insurance: "insurance", legal_compliance: "legal", real_estate: "real estate"};
const groups = [
  ["funding_recency", "Recent funding", 40, "cA", "When the company last raised equity. New money means the AI roadmap is funded now."],
  ["revenue", "Revenue", 25, "cB", "Mid-size companies have budget and buy fastest. The largest are slowed by procurement."],
  ["headcount", "Team size", 15, "cC", "Big enough to run a security review, small enough to buy quickly."]];
const ladder = (name, mx, c, why, rows) => h("div", {class: "ladder " + c},
  h("div", {class: "lh"}, h("b", {}, name), h("span", {class: "muted num"}, `up to ${mx}`)), h("p", {class: "why"}, why),
  h("table", {}, h("tbody", {}, rows.map(([lab, pts]) => h("tr", {}, h("td", {}, lab),
    h("td", {class: "r"}, h("span", {class: "cell"}, String(pts), h("span", {class: "sb"}, h("i", {style: `width:${(pts / mx * 100).toFixed(0)}%`})))))))));
groups.forEach(([k, name, mx, c, why]) => $("wt").append(ladder(name, mx, c, why,
  D.weights.filter(w => w.component === k).map(w => [LVL[w.level] || w.level, w.points]))));
const SIG = {"named customer category": "White Circle names customers in", "homepage tab": "On White Circle's homepage:",
  "dedicated landing page": "Has its own White Circle landing page:", "press-only mention": "Named as customers in press coverage:"};
const fit = [];
Object.keys(SIG).forEach(tier => {
  const rs = D.fit_rules.filter(r => r.kind === "vertical" && r.tier === tier && r.points > 0);
  if (rs.length) fit.push([`${SIG[tier]} ${rs.map(r => IND[r.key] || VERT(r.key)).join(", ")}`, Math.max(...rs.map(r => r.points))]);
});
D.fit_rules.filter(r => r.kind === "feature").forEach(r => fit.push(["Plus: ships an agent that takes actions (checked on its website)", r.points]));
$("wt").append(ladder("Fit with White Circle's market", 10, "cE",
  "Follows what White Circle already markets to. The best-matching industry counts once, an action-taking agent adds to it, and the total stops at 10.", fit),
  h("details", {class: "sch"}, h("summary", {}, "Where each fit signal comes from"),
    h("ul", {class: "flist", style: "margin-top:6px"}, D.fit_rules.filter(r => r.points > 0).map(r =>
      h("li", {}, h("b", {}, (IND[r.key] || VERT(r.key)) + ": "), h("span", {class: "muted"}, r.evidence))))));

