    r"(?i:bearer)\s+[A-Za-z0-9._\-]{20,}", r"(?i:api[_-]?key|secret|token|password)\s*[=:]\s*['\"]?[A-Za-z0-9._\-/+]{12,}",
    r"\b[A-Fa-f0-9]{40,}\b", r"\b[A-Za-z0-9+/_\-]{48,}={0,2}",
