  const show = () => { place(); p.hidden = false; b.setAttribute("aria-expanded", "true"); };
  const hide = () => { p.hidden = true; b.setAttribute("aria-expanded", "false"); };
  let pinned = false;
  b.addEventListener("mouseenter", show); b.addEventListener("mouseleave", () => { if (!pinned) hide(); });
  b.addEventListener("focus", show); b.addEventListener("blur", () => { if (!pinned) hide(); });
  b.addEventListener("click", () => { pinned = !pinned; pinned ? show() : hide(); });
  document.addEventListener("keydown", e => { if (e.key === "Escape" && !p.hidden) { pinned = false; hide(); b.focus(); } });
  document.addEventListener("click", e => { if (pinned && !p.contains(e.target) && e.target !== b) { pinned = false; hide(); } });
})();

